// Visuals come from Figma. Behaviour: WAI-ARIA menu pattern, recognised from the Figma structure (see the notes in the docs page).
import type { HTMLAttributes, ReactNode, KeyboardEvent } from 'react';

import { Children, cloneElement, isValidElement, useId, useState } from 'react';
import { Icon } from '../../icons/Icon';
import { ListItem } from '../ListItem/ListItem';
import styles from './DropdownMenu.module.css';

export interface DropdownMenuProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'state' | 'showSearch' | 'grouped'> {
  /** Figma: State. Default default. */
  state?: 'default' | 'loading' | 'empty';
  /** Figma: Show Search (boolean). Default false. */
  showSearch?: boolean;
  /** Figma: Grouped (boolean). Default false. */
  grouped?: boolean;
  /** Your own ListItem items instead of the Figma examples. DropdownMenu sets nothing on each one you do not set yourself. */
  children?: ReactNode;
  /** Renders a pseudo state statically for docs and visual tests: "hover", "pressed" or "focus". */
  'data-force-state'?: string;
}

export function DropdownMenu({ state = 'default', showSearch = false, grouped = false, children, onKeyDown, className, ...rest }: DropdownMenuProps) {
  const labelId = useId();
  const [active, setActive] = useState(-1);
  const itemProps = (i: number, _figma?: boolean, kind: string = 'item') => {
    if (kind === 'separator') return { role: 'separator' };
    if (kind === 'heading') return { role: 'presentation' };
    return { role: 'menuitem', id: `${labelId}-${i}`, 'data-ds-item': '', 'data-ds-index': i, ...(i === active ? { 'data-force-state': 'focus' } : {}) };
  };
  /** Arrow keys, Home and End move the active item; Enter and Space choose it. */
  const moveActive = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    const items = [...event.currentTarget.querySelectorAll<HTMLElement>('[data-ds-item]')];
    if (!items.length) return;
    const at = items.findIndex((x) => Number(x.dataset.dsIndex) === active);
    const step = ({ ArrowDown: 1, ArrowUp: -1 } as Record<string, number>)[event.key];
    const to = step !== undefined ? (at < 0 ? (step > 0 ? 0 : items.length - 1) : (at + step + items.length) % items.length) : event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : -1;
    if (to >= 0) {
      event.preventDefault();
      setActive(Number(items[to]!.dataset.dsIndex));
      items[to]!.scrollIntoView?.({ block: 'nearest' });
    } else if ((event.key === ' ' || event.key === 'Enter') && at >= 0) {
      event.preventDefault();
      items[at]!.click();
    }
  };
  const listed = !["loading","empty"].includes(String(state));
  const listProps = listed ? { role: 'menu', tabIndex: 0, 'aria-activedescendant': active >= 0 ? `${labelId}-${active}` : undefined, 'aria-labelledby': labelId, onKeyDown: moveActive } : { onKeyDown, 'aria-busy': state === "loading" || undefined };
  return (
    <div className={[styles.root, className].filter(Boolean).join(' ')} data-state={state} {...listProps} {...rest}>
      {showSearch && (
        <div className={styles.searchRow}>
          <span className={styles.searchIcon} aria-hidden="true"><Icon name="actionSearch16" /></span>
          <span className={styles.searchPlaceholder}>{"Search…"}</span>
        </div>
      )}
      {grouped && (
        <div className={styles.groupLabelWrap}>
          <span id={labelId} className={styles.groupLabel}>{"Group label"}</span>
        </div>
      )}
      <div className={styles.optionsList}>
        {children !== undefined
          ? Children.map(children, (child, i) => <span className={styles.option} key={i}>{isValidElement(child) && child.type === ListItem ? cloneElement(child, { ...{  }, ...(child.props as object), ...(itemProps(i, (child.props as { selected?: boolean }).selected, 'item') as object) }) : child}</span>)
          : (
            <>
              <span className={styles.option}><ListItem state="selected" hasTrailingControl {...(itemProps(0, false, "item") as object)} /></span>
              <span className={styles.option}><ListItem {...(itemProps(1, false, "item") as object)} /></span>
              <span className={styles.option}><ListItem data-force-state="hover" {...(itemProps(2, false, "item") as object)} /></span>
              <span className={styles.option}><ListItem disabled {...(itemProps(3, false, "item") as object)} /></span>
            </>
          )}
      </div>
      <div className={styles.loadingRow}>
        <span className={styles.loadingIcon} aria-hidden="true"><Icon name="statusLoading16" /></span>
        <span className={styles.loadingText}>{"Loading options…"}</span>
      </div>
      <div className={styles.emptyRow}>
        <span className={styles.emptyText}>{"No results found"}</span>
      </div>
    </div>
  );
}
